// Generic module and lesson pages. Module owners do not edit this file:
// they add lessons in src/modules/<their-module>/ and these pages render them.
import { Link, useParams } from 'react-router'
import { SITE_NAME, modules } from '../site'
import { completeLesson, useProgress } from '../progress'
import { ProgressBar } from '../components/ProgressBar'
import { NotFound } from './NotFound'

export function ModulePage() {
  const { moduleId } = useParams()
  const { perModule, isDone } = useProgress()
  const index = modules.findIndex((m) => m.id === moduleId)
  if (index < 0) return <NotFound />
  const module = modules[index]

  return (
    <>
      <title>{`${module.title} · ${SITE_NAME}`}</title>
      <h1 className="text-3xl font-extrabold">{module.title}</h1>
      <p className="mt-2 text-muted">{module.blurb}</p>
      <div className="mt-4">
        <ProgressBar value={perModule[index].percent} label={`${module.title} progress`} />
      </div>

      <ol className="mt-6 space-y-3">
        {module.lessons.map((lesson, n) => (
          <li key={lesson.id}>
            <Link
              to={`/modules/${module.id}/${lesson.id}`}
              className="card flex items-center justify-between gap-4 transition hover:shadow-md"
            >
              <span className="font-semibold">
                {n + 1}. {lesson.title}
              </span>
              <span className="shrink-0 text-sm text-muted">
                {isDone(module.id, lesson.id) ? '✓ Complete' : `+${lesson.xp} XP`}
              </span>
            </Link>
          </li>
        ))}
      </ol>
    </>
  )
}

export function LessonPage() {
  const { moduleId, lessonId } = useParams()
  const { isDone } = useProgress()
  const module = modules.find((m) => m.id === moduleId)
  const index = module?.lessons.findIndex((l) => l.id === lessonId) ?? -1
  if (!module || index < 0) return <NotFound />
  const lesson = module.lessons[index]
  const next = module.lessons[index + 1]
  const done = isDone(module.id, lesson.id)

  return (
    <>
      <title>{`${lesson.title} · ${SITE_NAME}`}</title>
      <Link to={`/modules/${module.id}`} className="text-sm text-muted underline hover:text-ink">
        ← {module.title}
      </Link>
      <h1 className="mt-2 text-3xl font-extrabold">{lesson.title}</h1>

      <article className="prose-lesson mt-6">
        <lesson.Component />
      </article>

      <div className="mt-10 flex flex-wrap items-center gap-3 border-t border-line pt-6">
        <button className="btn" disabled={done} onClick={() => completeLesson(module.id, lesson.id)}>
          {done ? '✓ Completed' : `Mark complete (+${lesson.xp} XP)`}
        </button>
        {next ? (
          <Link to={`/modules/${module.id}/${next.id}`} className="font-semibold text-brand underline">
            Next: {next.title} →
          </Link>
        ) : (
          <Link to="/learn" className="font-semibold text-brand underline">
            Back to the learning hub →
          </Link>
        )}
      </div>
    </>
  )
}
